# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 3: CLOTHES, ACCESSORIES AND ADJECTIVES (ENG.5.3)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Clothes (Giysiler)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• coat (kaban) · jacket (ceket)</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• raincoat (yağmurluk)</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• jumper / sweater (kazak)</text>\n  <text x="125" y="162" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• shirt (gömlek) · T-shirt (tişört)</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• trousers / jeans (pantolon/kot)</text>\n  <text x="125" y="206" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• dress (elbise) · skirt (etek)</text>\n  <text x="125" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">shoes, boots, socks, shorts</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Accessories (Aksesuarlar)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11.5" fill="#831843">• hat / cap (şapka / kep)</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#831843">• scarf / headscarf (atkı / başörtüsü)</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11.5" fill="#831843">• gloves (eldiven) · belt (kemer)</text>\n  <text x="350" y="162" text-anchor="middle" font-size="11.5" fill="#831843">• glasses / sunglasses (gözlük)</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11.5" fill="#831843">• handbag / bag (el çantası)</text>\n  <text x="350" y="206" text-anchor="middle" font-size="11.5" fill="#831843">• watch (kol saati) · umbrella (şemsiye)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">necklace, ring, earrings, bow</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Adjectives &amp; Verbs</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11.5" fill="#14532d">• thick (kalın) ↔ thin (ince)</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">• comfortable (rahat)</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11.5" fill="#14532d">• trendy / cool (modaya uygun / havalı)</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11.5" fill="#14532d">• fancy (süslü) ↔ ordinary (sıradan)</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11.5" fill="#14532d">• to wear (giymek/takmak)</text>\n  <text x="575" y="206" text-anchor="middle" font-size="11.5" fill="#14532d">• to try on (kıyafet denemek)</text>\n  <text x="575" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">outfit (kıyafet takımı / kombin)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING WHAT PEOPLE WEAR &amp; POSSESSIVE ADJECTIVES</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Simple Present for Clothing Habits</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• I / You / We / They + wear ...</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#78350f">  "I wear my comfortable shoes at school."</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#78350f">• He / She / It + wears (-s takısı) ...</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#78350f">  "She wears her thick coat in winter."</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11.5" fill="#78350f">• "What does he wear on rainy days?"</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">"He wears his yellow raincoat and boots."</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Possessive Adjectives (İyelik Sıfatları)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• I → my (benim) : my blue jacket</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#155e75">• You → your (senin/sizin) : your new cap</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">• He → his (onun - erkek) : his brown belt</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11.5" fill="#155e75">• She → her (onun - kız) : her silver ring</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11.5" fill="#155e75">• We → our (bizim) · They → their (onların)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">İyelik sıfatlarından sonra daima bir isim gelir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DAILY ROUTINES, ADVERBS OF FREQUENCY &amp; QUESTION TAGS</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Adverbs of Frequency &amp; Time</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#4c1d95">• always (100%) &gt; usually (80%)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#4c1d95">• sometimes (50%) &gt; rarely (15%) &gt; never (0%)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#4c1d95">• How often do you go shopping?</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" fill="#4c1d95">  "I sometimes go shopping at weekends."</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11.5" fill="#4c1d95">• What time does she read a magazine?</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">  "She reads a magazine at half past seven."</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Question Tags (Değil mi? - Onay Soruları)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Olumlu Cümle (+) → Olumsuz Tag (-)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">  "She reads a book every evening, doesn\'t she?"</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#14532d">  "You like trendy clothes, don\'t you?"</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11.5" fill="#14532d">• Olumsuz Cümle (-) → Olumlu Tag (+)</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11.5" fill="#14532d">  "He doesn\'t wear glasses, does he?"</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">  "They don\'t play video games, do they?"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
